import string

def encode_shift(s: str) -> str:
    """
    Returns encoded string by shifting every alphabetical character by 5 positions in the alphabet.
    Non-alphabet characters are left unchanged.
    """
    result = []
    for ch in s:
        if 'a' <= ch <= 'z':
            # Shift within lowercase alphabet
            shifted = chr((ord(ch) - ord('a') + 5) % 26 + ord('a'))
            result.append(shifted)
        elif 'A' <= ch <= 'Z':
            # Shift within uppercase alphabet
            shifted = chr((ord(ch) - ord('A') + 5) % 26 + ord('A'))
            result.append(shifted)
        else:
            # Non-alphabetic characters remain unchanged
            result.append(ch)
    return "".join(result)

def decode_shift(s: str) -> str:
    """
    Takes as input a string encoded with encode_shift and returns the original (decoded) string.
    """
    result = []
    for ch in s:
        if 'a' <= ch <= 'z':
            shifted_back = chr((ord(ch) - ord('a') - 5) % 26 + ord('a'))
            result.append(shifted_back)
        elif 'A' <= ch <= 'Z':
            shifted_back = chr((ord(ch) - ord('A') - 5) % 26 + ord('A'))
            result.append(shifted_back)
        else:
            result.append(ch)  # Non-alphabetic characters unchanged
    return "".join(result)
