import math

def is_multiply_prime(a):
    """
    Return True if the given number a (less than 100) can be expressed as the product of exactly three
    prime numbers (not necessarily distinct), else False.
    """
    if a < 2 or a >= 100:
        return False

    def is_prime(n):
        if n < 2:
            return False
        if n == 2:
            return True
        if n % 2 == 0:
            return False
        for i in range(3, int(math.isqrt(n)) + 1, 2):
            if n % i == 0:
                return False
        return True

    # Find all primes up to a (since the largest prime factor ≤ a)
    max_prime = int(math.isqrt(a)) + 1
    while max_prime * max_prime > a and max_prime > 2:
        max_prime -= 1
    # Rebuild the list for safety
    primes = [p for p in range(2, max_prime + 1) if is_prime(p)]

    # Try all triplets of primes (with replacement, order doesn't matter)
    n_primes = len(primes)
    found = False
    for i in range(n_primes):
        p1 = primes[i]
        if p1 > a:
            break
        for j in range(i, n_primes):  # allow repeats (e.g. 2*2*5)
            p2 = primes[j]
            if p2 * p1 > a:
                break
            for k in range(j, n_primes):  # allow repeats
                p3 = primes[k]
                product = p1 * p2 * p3
                if product == a:
                    found = True
                    break
                if product > a:
                    break
            if found:
                break
        if found:
            break
    return found
