def check_dict_case(d):
    """
    Given a dictionary, return True if all keys are strings in lower case
    or all keys are strings in upper case. Return False if any key is not a string,
    if there are mixed cases, or if the dictionary is empty.
    """
    # If the dictionary is empty, return False immediately
    if not d:
        return False

    # Collect the case (lower, upper, or neither) for each string key
    key_cases = []
    for key in d:
        if not isinstance(key, str):
            # Non-string keys invalidate the condition
            return False
        if key.islower():
            key_cases.append('lower')
        elif key.isupper():
            key_cases.append('upper')
        else:
            # Mixed case (has both upper and lower), or neither (e.g. 'CamelCase')
            return False

    # All keys must agree on being all lower or all upper
    if not key_cases or len(set(key_cases)) == 1:
        return True  # Either all lower or all upper (since set size 1 and not empty)
    return False

