import re

def valid_date(date):
    """
    Validates a date string in 'mm-dd-yyyy' format.
    Rules checked:
    1. Non-empty string
    2. Correct format mm-dd-yyyy
    3. Months 1-12
    4. Days appropriate for the month (accounting for leap years in February)
    """
    # Check non-empty and correct format using regex
    pattern = r'^\d{2}-\d{2}-\d{4}$'
    if not isinstance(date, str) or not re.match(pattern, date):
        return False

    # Split into components
    parts = date.split('-')
    if len(parts) != 3:
        return False  # extra safety, shouldn't happen with the regex
    try:
        month = int(parts[0])
        day = int(parts[1])
        year = int(parts[2])
    except ValueError:
        return False  # in case digits were missing (should be caught by regex)

    # Rule 3: months must be between 1 and 12
    if month < 1 or month > 12:
        return False

    # Determine max days in month
    if month in [1, 3, 5, 7, 8, 10, 12]:
        max_day = 31
    elif month in [4, 6, 9, 11]:
        max_day = 30
    elif month == 2:
        # Leap year check
        if (year % 4 == 0 and year % 100 != 0) or (year % 400 == 0):
            max_day = 29
        else:
            max_day = 28
    else:
        return False  # should not reach here, but for completeness

    if day < 1 or day > max_day:
        return False

    return True
