def can_arrange(arr):
    """
    Returns the largest index i such that arr[i] < arr[i-1].
    If no such index exists, returns -1.
    """
    for i in range(1, len(arr)):
        if arr[i] < arr[i - 1]:
            max_idx = i
            # Continue searching to the right for a possibly larger index
            for j in range(i + 1, len(arr)):
                if arr[j] < arr[j - 1]:
                    max_idx = j
            return max_idx
    return -1
